import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, vec2, length, float, sin, positionLocal, smoothstep, abs } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Shape, ExtrudeGeometry, DirectionalLight, Color, Box3, Vector3, AdditiveBlending } = ctx.THREE;

  const root = new Group();
  root.name = 'nav-dock';

  const disposables = [];
  const tweens = [];
  const track = (t) => { tweens.push(t); return t; };

  const colors = config.intent?.visualSpec?.colors ?? {};
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';
  const INACTIVE = '#a6adba';
  const GRAD_TOP = (colors.gradientStops && colors.gradientStops[0]?.hex) || '#1b1b23';
  const GRAD_BOT = (colors.gradientStops && colors.gradientStops[1]?.hex) || '#101015';

  // ---------------------------------------------------------------
  // STAGE BACKDROP — vertical gradient + vignette + a soft symmetric
  // horizontal luminance band baked INTO the shader at the rail's y.
  // (Replaces the previous misaligned backing slab: the band is
  // centered by construction, so no compositing artifact is possible.)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const u = uv();
    const grad = mix(color(GRAD_BOT), color(GRAD_TOP), u.y);
    const vig = float(1).sub(length(u.sub(vec2(0.5, 0.5))).mul(0.8)).clamp(0.5, 1.0);
    // soft horizontal band behind the rail (rail sits at y=0 -> uv.y=0.5)
    const band = float(1).sub(smoothstep(0.0, 0.16, abs(u.y.sub(0.5)))).mul(0.22);
    // gentle horizontal falloff so the band feels machined, not painted edge-to-edge
    const bandX = float(1).sub(smoothstep(0.18, 0.5, abs(u.x.sub(0.5))));
    const grain = sin(u.y.mul(720.0)).mul(0.012).add(1.0);
    backdropMat.colorNode = grad.mul(vig).mul(grain).add(color('#2a2a34').mul(band.mul(bandX)));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // NODE-LOCAL LIGHTS — neutral top key assist to make the brushed
  // metal read, plus a LOW accent rim from below aimed only at the
  // rail underside (kept dim so accent never tints text/underline).
  // ---------------------------------------------------------------
  const topSpec = new DirectionalLight(new Color(PAPER), 1.1);
  topSpec.position.set(0.8, 3.2, 2.4);
  topSpec.target.position.set(0, 0, 0.15);
  root.add(topSpec);
  root.add(topSpec.target);

  const rim = new DirectionalLight(new Color(ACCENT), 0.4);
  rim.position.set(-2.2, -2.0, 0.8);
  rim.target.position.set(0, -0.2, 0.15);
  root.add(rim);
  root.add(rim.target);

  // ---------------------------------------------------------------
  // DOCK GROUP (rises in on mount)
  // ---------------------------------------------------------------
  const dock = new Group();
  root.add(dock);

  // ---------------------------------------------------------------
  // CONTACT SHADOW — radial, 35% opacity, offset 0.06 down
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(4.3, 0.95);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = float(1).sub(length(uv().sub(vec2(0.5, 0.5))).mul(2.0)).clamp(0, 1).mul(0.35);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.06, 0.0);
  dock.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // MACHINED RAIL — rounded 3.6 x 0.5, chamfer 0.02, brushed PBR.
  // Sharper brushed streaks + a vertical spec ramp toward the top
  // chamfer so the metal reads machined, not soft.
  // ---------------------------------------------------------------
  const RAIL_W = 3.6;
  const RAIL_H = 0.5;
  const RAIL_R = 0.1;
  const railShape = new Shape();
  const hw = RAIL_W / 2, hh = RAIL_H / 2, r = RAIL_R;
  railShape.moveTo(-hw + r, -hh);
  railShape.lineTo(hw - r, -hh);
  railShape.absarc(hw - r, -hh + r, r, -Math.PI / 2, 0, false);
  railShape.lineTo(hw, hh - r);
  railShape.absarc(hw - r, hh - r, r, 0, Math.PI / 2, false);
  railShape.lineTo(-hw + r, hh);
  railShape.absarc(-hw + r, hh - r, r, Math.PI / 2, Math.PI, false);
  railShape.lineTo(-hw, -hh + r);
  railShape.absarc(-hw + r, -hh + r, r, Math.PI, Math.PI * 1.5, false);

  const railGeo = new ExtrudeGeometry(railShape, {
    depth: 0.08,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 16,
  });
  const railMat = new MeshPhysicalNodeMaterial();
  {
    const t = positionLocal.y.add(hh).div(RAIL_H).clamp(0, 1);
    // brushed streaks along x — two frequencies for machined texture
    const streak = sin(positionLocal.x.mul(180.0)).mul(0.03)
      .add(sin(positionLocal.x.mul(47.0)).mul(0.02))
      .add(1.0);
    // spec ramp brightening toward the top chamfer
    const topRamp = smoothstep(0.72, 1.0, t).mul(0.35);
    const base = mix(color(GRAD_BOT), color(GRAD_TOP), t);
    railMat.colorNode = base.mul(streak).add(color('#4a4e58').mul(topRamp));
    // roughness tightens near the top edge so the key light draws a crisp line
    railMat.roughnessNode = float(0.55).sub(smoothstep(0.8, 1.0, t).mul(0.18));
  }
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.clearcoatRoughness = 0.3;
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0.15);
  dock.add(rail);
  disposables.push(railGeo, railMat);

  // continuous specular hairline along the top chamfer
  const specGeo = new PlaneGeometry(RAIL_W - RAIL_R * 2, 0.008);
  const specMat = new MeshBasicNodeMaterial();
  {
    const fall = float(1).sub(smoothstep(0.32, 0.5, abs(uv().x.sub(0.5))));
    specMat.colorNode = color('#aab0bc').mul(fall.mul(0.7).add(0.3));
  }
  const specLine = new Mesh(specGeo, specMat);
  specLine.position.set(0, hh - 0.004, 0.26);
  dock.add(specLine);
  disposables.push(specGeo, specMat);

  // ---------------------------------------------------------------
  // ENTRIES — five, centers 0.68 apart; labels normalized to a fixed
  // cap height in scene units.
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labels = items.length
    ? items.map((it) => String(it.text))
    : ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];
  const targets = ['hub-home', 'hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];
  const SPACING = 0.68;
  const startX = -SPACING * 2;
  const TEXT_Z = 0.27;
  const CAP_H = 0.085;
  const MAX_LABEL_W = 0.56;

  let activeIndex = 0;
  let hoveredIndex = -1;

  const entries = [];

  const fitLabel = (obj) => {
    const box = new Box3().setFromObject(obj);
    const size = new Vector3();
    box.getSize(size);
    if (size.y > 1e-6 && isFinite(size.y)) {
      let s = CAP_H / size.y;
      if (size.x * s > MAX_LABEL_W) s = MAX_LABEL_W / size.x;
      obj.scale.multiplyScalar(s);
      const box2 = new Box3().setFromObject(obj);
      const c = new Vector3();
      box2.getCenter(c);
      obj.position.x = -c.x;
      obj.position.y = -c.y;
    } else {
      obj.scale.multiplyScalar(CAP_H / 13);
    }
  };

  const tweenTextColor = (obj, hexTo, dur) => {
    const mats = [];
    obj.traverse((c) => { if (c.material && c.material.color) mats.push(c.material); });
    if (!mats.length) return;
    const from = mats[0].color.clone();
    const to = new Color(hexTo);
    const proxy = { t: 0 };
    track(gsap.to(proxy, {
      t: 1,
      duration: dur,
      ease: 'power2.out',
      onUpdate: () => {
        const c = from.clone().lerp(to, proxy.t);
        for (const m of mats) m.color.copy(c);
      },
    }));
  };

  for (let i = 0; i < 5; i++) {
    const cell = new Group();
    cell.position.set(startX + i * SPACING, 0, TEXT_Z);

    const label = ctx.fontAtlas.createText(labels[i] ?? '', {
      fontSize: 13,
      color: i === activeIndex ? PAPER : INACTIVE,
      align: 'center',
      letterSpacingPx: 1.04,
    });
    fitLabel(label);
    cell.add(label);

    const hitGeo = new PlaneGeometry(0.6, 0.34);
    const hitMat = new MeshBasicNodeMaterial();
    hitMat.transparent = true;
    hitMat.opacity = 0;
    hitMat.depthWrite = false;
    const hit = new Mesh(hitGeo, hitMat);
    hit.position.set(0, 0, 0.02);
    hit.userData.entryIndex = i;
    hit.userData.interactive = true;
    cell.add(hit);
    disposables.push(hitGeo, hitMat);

    dock.add(cell);
    entries.push({ cell, label, hit, index: i });
  }

  // ---------------------------------------------------------------
  // ACTIVE UNDERLINE — 0.28 x 0.025 in EXACT #ff2a38.
  // UNLIT basic material: the previous lit/emissive-1.8 version was
  // desaturated to salmon by tone mapping + the accent rim light.
  // A subtle additive glow plane supplies the emissive read without
  // pushing the core color off-palette.
  // ---------------------------------------------------------------
  const barGroup = new Group();
  barGroup.position.set(startX, -0.115, TEXT_Z);
  dock.add(barGroup);

  const glowGeo = new PlaneGeometry(0.44, 0.11);
  const glowMat = new MeshBasicNodeMaterial();
  glowMat.transparent = true;
  glowMat.depthWrite = false;
  glowMat.blending = AdditiveBlending;
  glowMat.colorNode = color(ACCENT);
  glowMat.opacityNode = float(1).sub(length(uv().sub(vec2(0.5, 0.5)).mul(vec2(2.0, 2.2)))).clamp(0, 1).mul(0.3);
  const glow = new Mesh(glowGeo, glowMat);
  glow.position.set(0, 0, -0.005);
  barGroup.add(glow);
  disposables.push(glowGeo, glowMat);

  const barGeo = new PlaneGeometry(0.28, 0.025);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = color(ACCENT);
  const bar = new Mesh(barGeo, barMat);
  barGroup.add(bar);
  disposables.push(barGeo, barMat);

  // ---------------------------------------------------------------
  // MOUNT — rise-in y +0.4 -> 0, 700ms, power3.out
  // ---------------------------------------------------------------
  dock.position.y = -0.4;
  track(gsap.to(dock.position, { y: 0, duration: 0.7, ease: 'power3.out' }));

  // ---------------------------------------------------------------
  // INTERACTION
  // ---------------------------------------------------------------
  const setActive = (idx) => {
    if (idx === activeIndex) return;
    const prev = entries[activeIndex];
    const next = entries[idx];
    tweenTextColor(prev.label, INACTIVE, 0.16);
    tweenTextColor(next.label, PAPER, 0.16);
    activeIndex = idx;
    track(gsap.to(barGroup.position, {
      x: startX + idx * SPACING,
      duration: 0.26,
      ease: 'back.out(1.2)',
    }));
  };

  const onHoverIn = (idx) => {
    if (idx === hoveredIndex) return;
    if (hoveredIndex >= 0 && hoveredIndex !== activeIndex) {
      tweenTextColor(entries[hoveredIndex].label, INACTIVE, 0.16);
    }
    hoveredIndex = idx;
    if (idx >= 0 && idx !== activeIndex) {
      tweenTextColor(entries[idx].label, PAPER, 0.16);
    }
  };

  const onHoverOut = () => {
    if (hoveredIndex >= 0 && hoveredIndex !== activeIndex) {
      tweenTextColor(entries[hoveredIndex].label, INACTIVE, 0.16);
    }
    hoveredIndex = -1;
  };

  const pressEntry = (idx) => {
    const cell = entries[idx].cell;
    track(gsap.to(cell.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' }));
    track(gsap.to(cell.position, { z: TEXT_Z - 0.03, duration: 0.12, ease: 'power2.out' }));
  };

  const releaseEntry = (idx) => {
    const cell = entries[idx].cell;
    track(gsap.to(cell.scale, { x: 1, y: 1, z: 1, duration: 0.24, ease: 'power2.out' }));
    track(gsap.to(cell.position, { z: TEXT_Z, duration: 0.24, ease: 'power2.out' }));
  };

  const indexFromHit = (hit) => {
    const obj = hit && (hit.object ?? hit);
    if (!obj) return -1;
    let cur = obj;
    while (cur) {
      if (cur.userData && typeof cur.userData.entryIndex === 'number') return cur.userData.entryIndex;
      cur = cur.parent;
    }
    return -1;
  };

  let pressedIndex = -1;

  root.userData.handlers = {
    pointermove: (hit) => {
      const idx = indexFromHit(hit);
      if (idx >= 0) onHoverIn(idx);
      else onHoverOut();
    },
    pointerleave: () => onHoverOut(),
    pointerdown: (hit) => {
      const idx = indexFromHit(hit);
      if (idx < 0) return;
      pressedIndex = idx;
      pressEntry(idx);
    },
    pointerup: () => {
      if (pressedIndex >= 0) releaseEntry(pressedIndex);
      pressedIndex = -1;
    },
    click: (hit) => {
      const idx = indexFromHit(hit);
      if (idx < 0) return;
      setActive(idx);
      ctx.emit('navigate', { to: targets[idx] });
    },
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const t of tweens) t && t.kill && t.kill();
    tweens.length = 0;
    gsap.killTweensOf(dock.position);
    gsap.killTweensOf(barGroup.position);
    for (const e of entries) {
      gsap.killTweensOf(e.cell.scale);
      gsap.killTweensOf(e.cell.position);
      e.label.traverse((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose();
      });
    }
    for (const d of disposables) d && d.dispose && d.dispose();
  };

  return root;
}
